/* textbook.js: turns the core lessons into a numbered textbook (data in textbook-data.js, generated by build_book.py).
   On each core lesson:  chapter/section numbering, section objectives, a full textbook treatment with numbered
   equations and worked examples, key points, key terms with pop-up definitions, and exercises with worked solutions.
   On each pathway overview: a chapter opener (aims, prerequisites, sections) and a chapter review.
   New study pages:  /study/read/N/  (a chapter as one continuous, printable page), /study/glossary/,
   /study/equations/, /study/problems/.  Exercise self-ratings are per-viewer browser storage (try/catch guarded). */
(function () {
  'use strict';
  const B = window.NG_BOOK; if (!B) return;
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const PATH = () => (window.ngPath ? ngPath() : '/');
  const L = () => document.getElementById('lesson');
  const ROMAN = { I: 'I', II: 'II', III: 'III', IV: 'IV', V: 'V' };

  /* ---------- index ---------- */
  const SEC = new Map(), ORDER = [];
  B.chapters.forEach(c => c.sections.forEach((s, i) => { const e = { c, s, i }; SEC.set(s.route, e); ORDER.push(e); }));
  const overviewOf = c => '/pathways/' + pathSlugs[c.pathway] + '/';
  const CH_BY_OVERVIEW = new Map(B.chapters.map(c => [overviewOf(c), c]));
  const label = route => { try { const p = ngAllPages().find(x => x.href === route); if (p) return p.label; } catch (e) {} return route; };
  const strip = h => { const d = document.createElement('div'); d.innerHTML = h; d.querySelectorAll('math').forEach(m => { const a = m.querySelector('annotation'); m.replaceWith(a ? ' ' + a.textContent.replace(/\\(text|mathrm|operatorname)\{([^}]*)\}/g, '$2').replace(/\\/g, '').replace(/[{}]/g, '') + ' ' : ' '); }); return d.textContent.replace(/\s+/g, ' ').trim(); };
  const chTitleText = c => strip(c.title);

  /* ---------- exercise self-ratings (light per-viewer convenience) ---------- */
  const EXK = 'ng-tb-ex-v1';
  const exGet = () => { try { return JSON.parse(localStorage.getItem(EXK) || '{}') || {}; } catch (e) { return {}; } };
  const exSet = (id, v) => { try { const o = exGet(); if (v) o[id] = v; else delete o[id]; localStorage.setItem(EXK, JSON.stringify(o)); } catch (e) {} };
  const KIND = { calc: 'Calculate', concept: 'Explain', derive: 'Derive' };

  /* ---------- HTML builders ---------- */
  const objHTML = (items, title = 'After this section you can') => `<section class="tb-objectives" aria-label="Learning objectives"><p class="tb-label">${title}</p><ul>${items.map(o => `<li>${o}</li>`).join('')}</ul></section>`;
  const termsHTML = ids => `<dl class="tb-terms">${ids.map(id => { const g = B.glossary[id]; return g ? `<div><dt><a href="/study/glossary/?t=${id}">${g.term}</a></dt><dd>${g.def}</dd></div>` : ''; }).join('')}</dl>`;
  function problemsHTML(s, opts = {}) {
    const R = exGet();
    return `<ol class="tb-problems">${s.problems.map((p, k) => {
      const id = s.num + '.' + (k + 1), r = R[id] || '';
      return `<li class="tb-problem" data-ex="${id}" id="ex-${id.replace(/\./g, '-')}"><div class="tb-phead"><span class="tb-pnum">${opts.prefix || ''}${id}</span><span class="tb-kind tb-k-${p.kind}">${KIND[p.kind] || p.kind}</span>${r ? `<span class="tb-rated tb-r-${r}">${r === 'got' ? '✓ Solved' : '↻ Review again'}</span>` : ''}</div>
        <div class="tb-q">${p.q}</div>
        <details class="tb-sol"><summary>Show worked solution</summary><div class="tb-a">${p.a}</div>
          <div class="tb-rate" role="group" aria-label="How did it go?"><span>How did it go?</span><button type="button" data-rate="got" aria-pressed="${r === 'got'}">I got it</button><button type="button" data-rate="again" aria-pressed="${r === 'again'}">Review again</button></div></details></li>`;
    }).join('')}</ol>`;
  }
  const summaryHTML = s => `<div class="tb-keypoints"><p class="tb-label">Key points · §${s.num}</p><ul>${s.summary.map(x => `<li>${x}</li>`).join('')}</ul></div>`;
  const secLink = (e, dir) => e ? `<a class="tb-bn-${dir}" href="${e.s.route}"><small>${dir === 'prev' ? '← Previous section' : 'Next section →'}</small><span>§${e.s.num} ${esc(label(e.s.route))}</span></a>` : '<span></span>';

  /* ---------- decorate a core lesson ---------- */
  function decorateSection(Ls, e) {
    if (Ls.querySelector('.tb-kicker')) return;
    const { c, s } = e, hero = Ls.querySelector('.hero'), h1 = hero && hero.querySelector('h1');
    if (!hero || !h1) return;
    h1.insertAdjacentHTML('afterbegin', `<span class="tb-secnum">${s.num}</span>`);
    h1.insertAdjacentHTML('beforebegin', `<p class="tb-kicker"><a href="${overviewOf(c)}">Chapter ${c.n} · ${c.title}</a><span> · Section ${s.num}</span></p>`);
    const pill = hero.querySelector('.pill'); if (pill && !pill.dataset.tb) { pill.dataset.tb = 1; pill.textContent = `PART ${c.part} · SECTION ${s.num}`; }
    const jumps = Ls.querySelector('nav.page-jumps');
    const objBox = objHTML(s.obj);
    if (jumps) jumps.insertAdjacentHTML('beforebegin', objBox); else hero.insertAdjacentHTML('afterend', objBox);
    if (jumps && !jumps.querySelector('[href="#text"]')) {
      const idea = jumps.querySelector('[href="#idea"]'); idea && idea.insertAdjacentHTML('afterend', '<a href="#text">Text</a>');
      const chk = jumps.querySelector('[href="#check"]'); (chk || jumps.lastElementChild).insertAdjacentHTML('afterend', '<a href="#exercises">Exercises</a>');
    }
    const textSec = `<section class="lesson-section tb-text" id="text"><p class="eyebrow">Textbook · Section ${s.num}</p><h2>The full treatment</h2><div class="tb-prose">${s.body}</div>${summaryHTML(s)}</section>`;
    const idea = Ls.querySelector('#idea');
    if (idea) idea.insertAdjacentHTML('afterend', textSec); else (jumps || hero).insertAdjacentHTML('afterend', textSec);
    const endSec = `<section class="lesson-section tb-end" id="exercises"><p class="eyebrow">Textbook · Section ${s.num}</p><h2>Key terms and exercises</h2>
      <h3>Key terms</h3>${termsHTML(s.terms)}
      <h3 class="tb-exh">Exercises</h3><p class="muted">Work each one on paper first, then open the solution and rate yourself. Ratings are kept in this browser and collected on the <a href="/study/problems/">exercises page</a>.</p>${problemsHTML(s)}</section>`;
    const anchor = Ls.querySelector('#check') || Ls.querySelector('#reading') || Ls.querySelector('#text');
    anchor.insertAdjacentHTML('afterend', endSec);
    const k = ORDER.indexOf(e), foot = Ls.querySelector(':scope > footer');
    const nav = `<nav class="tb-booknav" aria-label="Textbook navigation">${secLink(ORDER[k - 1], 'prev')}<a class="tb-bn-mid" href="/study/read/${c.n}/">Read Chapter ${c.n} as one page</a>${secLink(ORDER[k + 1], 'next')}</nav>`;
    if (foot) foot.insertAdjacentHTML('beforebegin', nav); else Ls.insertAdjacentHTML('beforeend', nav);
  }

  /* ---------- decorate a chapter opener (pathway overview) ---------- */
  function decorateChapter(Ls, c) {
    if (Ls.querySelector('.tb-kicker')) return;
    const hero = Ls.querySelector('.hero'), h1 = hero && hero.querySelector('h1'); if (!h1) return;
    const short = h1.textContent.trim();
    h1.insertAdjacentHTML('beforebegin', `<p class="tb-kicker"><span>Part ${c.part} · ${esc(B.parts[c.part])}</span><span> · in the sidebar: “${esc(short)}”</span></p>`);
    h1.innerHTML = `<span class="tb-chnum">Chapter ${c.n}</span>${c.title}`;
    const pill = hero.querySelector('.pill'); if (pill) pill.textContent = `PART ${c.part} · CHAPTER ${c.n} OF ${B.chapters.length}`;
    const nEx = c.sections.reduce((a, s) => a + s.problems.length, 0), R = exGet(), solved = c.sections.reduce((a, s) => a + s.problems.filter((_, k) => R[s.num + '.' + (k + 1)] === 'got').length, 0);
    hero.insertAdjacentHTML('afterend', `<section class="tb-opener"><p class="tb-label">Chapter ${c.n} · ${c.title}</p>${c.intro.map(p => `<p>${p}</p>`).join('')}
      <div class="tb-opener-grid"><div>${objHTML(c.obj, 'Chapter objectives')}</div><div><p class="tb-label">Before you start</p><ul class="tb-prereq">${c.prereq.map(x => `<li>${x}</li>`).join('')}</ul>
      <p class="tb-label">Sections</p><ol class="tb-toc-mini">${c.sections.map(s => `<li><a href="${s.route}"><b>${s.num}</b> ${esc(label(s.route))}</a></li>`).join('')}</ol>
      <div class="tb-opener-cta"><a class="primary" href="/study/read/${c.n}/">Read the chapter as one page →</a><a class="secondary" href="/study/problems/?ch=${c.n}">Chapter exercises (${solved}/${nEx} solved)</a></div></div></div></section>`);
    const foot = Ls.querySelector(':scope > footer');
    const review = `<section class="lesson-section tb-review"><p class="eyebrow">Chapter ${c.n} review</p><h2>What this chapter establishes</h2>
      ${c.sections.map(s => `<div class="tb-review-sec"><h3><a href="${s.route}">§${s.num} ${esc(label(s.route))}</a></h3><ul>${s.summary.map(x => `<li>${x}</li>`).join('')}</ul></div>`).join('')}
      <details class="tb-eqlist"><summary>All ${c.sections.reduce((a, s) => a + s.eqs.length, 0)} numbered equations in this chapter</summary>${c.sections.map(s => s.eqs.map(q => eqRow(q, s)).join('')).join('')}</details></section>`;
    if (foot) foot.insertAdjacentHTML('beforebegin', review); else Ls.insertAdjacentHTML('beforeend', review);
  }
  const eqRow = (q, s) => `<div class="tb-eqrow"><a class="tb-eqrow-num" href="${s.route}">(${q.num})</a><div class="tb-eq-body">${q.html}</div></div>`;

  /* ---------- reader view: one chapter, continuous ---------- */
  function renderReader(n) {
    const c = B.chapters.find(x => x.n === n) || B.chapters[0], prev = B.chapters.find(x => x.n === c.n - 1), next = B.chapters.find(x => x.n === c.n + 1);
    document.title = `Chapter ${c.n}: ${chTitleText(c)} · Little Neural Guide`;
    L().innerHTML = `<div class="breadcrumbs"><a href="/">Home</a><span>›</span><a href="/study/">Study hub</a><span>›</span><a href="/study/read/1/">Core text</a><span>›</span><span>Chapter ${c.n}</span></div>
      <div class="tb-reader">
      <div class="hero"><span class="pill">PART ${c.part} · ${esc(B.parts[c.part]).toUpperCase()} · READING VIEW</span><p class="tb-kicker"><span>Chapter ${c.n} of ${B.chapters.length}</span></p><h1>${c.title}</h1>
        <div class="tb-reader-tools"><select id="tb-ch" aria-label="Choose a chapter">${B.chapters.map(x => `<option value="${x.n}" ${x.n === c.n ? 'selected' : ''}>Chapter ${x.n}: ${esc(chTitleText(x))}</option>`).join('')}</select>
        <button type="button" class="secondary" id="tb-print">Print or save as PDF</button><a class="secondary" href="${overviewOf(c)}">Interactive chapter →</a></div></div>
      <section class="tb-opener">${c.intro.map(p => `<p>${p}</p>`).join('')}<div class="tb-opener-grid"><div>${objHTML(c.obj, 'Chapter objectives')}</div><div><p class="tb-label">Before you start</p><ul class="tb-prereq">${c.prereq.map(x => `<li>${x}</li>`).join('')}</ul>
        <p class="tb-label">In this chapter</p><ol class="tb-toc-mini">${c.sections.map(s => `<li><a href="#sec-${s.num.replace('.', '-')}"><b>${s.num}</b> ${esc(label(s.route))}</a></li>`).join('')}</ol></div></div></section>
      ${c.sections.map(s => `<article class="tb-rsec" id="sec-${s.num.replace('.', '-')}"><h2><span class="tb-secnum">${s.num}</span>${esc(label(s.route))}</h2>${objHTML(s.obj)}
        <div class="tb-prose">${s.body}</div>${summaryHTML(s)}<p class="tb-open"><a href="${s.route}">Open §${s.num} with its interactive experiment, code and quiz →</a></p></article>`).join('')}
      <section class="tb-rsec tb-chex" id="chapter-exercises"><h2>Exercises for Chapter ${c.n}</h2><p class="muted">Solutions are folded under each exercise. Rate yourself to track progress on the exercises page.</p>
        ${c.sections.map(s => `<h3>§${s.num} ${esc(label(s.route))}</h3>${problemsHTML(s)}`).join('')}</section>
      <section class="tb-rsec tb-glossch"><h2>Terms introduced in Chapter ${c.n}</h2>${termsHTML([...new Set(c.sections.flatMap(s => s.terms))])}</section>
      <nav class="tb-booknav" aria-label="Chapters">${prev ? `<a class="tb-bn-prev" href="/study/read/${prev.n}/"><small>← Previous chapter</small><span>${prev.n}. ${esc(chTitleText(prev))}</span></a>` : '<span></span>'}<a class="tb-bn-mid" href="/study/read/1/#tb-contents">Contents</a>${next ? `<a class="tb-bn-next" href="/study/read/${next.n}/"><small>Next chapter →</small><span>${next.n}. ${esc(chTitleText(next))}</span></a>` : '<span></span>'}</nav>
      </div>`;
    L().querySelector('#tb-ch').addEventListener('change', ev => ngGo('/study/read/' + ev.target.value + '/'));
    L().querySelector('#tb-print').addEventListener('click', () => { try { window.print(); } catch (e) {} });
  }

  /* ---------- glossary ---------- */
  function renderGlossary() {
    document.title = 'Glossary · Little Neural Guide';
    const ids = Object.keys(B.glossary).sort((a, b) => B.glossary[a].plain.localeCompare(B.glossary[b].plain, 'en', { sensitivity: 'base' }));
    const letter = id => (B.glossary[id].plain.match(/[A-Za-z]/) || ['#'])[0].toUpperCase();
    const letters = [...new Set(ids.map(letter))];
    L().innerHTML = stHeader('Glossary', `Every key term of the core text (${ids.length}), with its definition and the section that introduces it. Terms are also underlined in the text; hover or tap one for its definition.`, `CORE TEXT · ${ids.length} TERMS`)
      + `<div class="tb-gl-tools"><input type="search" id="tb-gq" placeholder="Filter terms…" aria-label="Filter glossary"><nav class="tb-az" aria-label="Jump to letter">${letters.map(l => `<a href="#gl-${l}">${l}</a>`).join('')}</nav></div>
      <div class="tb-glossary">${letters.map(l => `<section id="gl-${l}"><h2>${l}</h2><dl>${ids.filter(id => letter(id) === l).map(id => { const g = B.glossary[id]; return `<div class="tb-gl" id="term-${id}" data-q="${esc((g.plain + ' ' + strip(g.def)).toLowerCase())}"><dt>${g.term}</dt><dd>${g.def}${g.sec ? ` <a class="tb-glsec" href="${g.route}">Introduced in §${g.sec} →</a>` : ''}</dd></div>`; }).join('')}</dl></section>`).join('')}</div>`;
    const q = L().querySelector('#tb-gq');
    q.addEventListener('input', () => { const v = q.value.trim().toLowerCase(); L().querySelectorAll('.tb-gl').forEach(d => { d.hidden = v && !d.dataset.q.includes(v); }); L().querySelectorAll('.tb-glossary section').forEach(s => { s.hidden = ![...s.querySelectorAll('.tb-gl')].some(d => !d.hidden); }); });
    const want = (location.hash.split('?')[1] || '').match(/(?:^|&)t=([a-z0-9-]+)/);
    if (want) setTimeout(() => { const el = document.getElementById('term-' + want[1]); if (el) { el.scrollIntoView({ block: 'center' }); el.classList.add('tb-flash'); } }, 60);
  }

  /* ---------- key equations ---------- */
  function renderEquations() {
    document.title = 'Key equations · Little Neural Guide';
    const n = B.chapters.reduce((a, c) => a + c.sections.reduce((b, s) => b + s.eqs.length, 0), 0);
    L().innerHTML = stHeader('Key equations', `All ${n} numbered equations of the core text, by chapter and section. Click a number to open its section; use “TeX” to copy the LaTeX source for your own notes or papers.`, `CORE TEXT · ${n} EQUATIONS`)
      + B.chapters.map(c => `<section class="lesson-section"><p class="eyebrow">Part ${c.part} · Chapter ${c.n}</p><h2>${c.title}</h2>${c.sections.map(s => `<h3><a href="${s.route}">§${s.num} ${esc(label(s.route))}</a></h3>${s.eqs.map(q => `<div class="tb-eq" id="eq-${q.num.replace(/\./g, '-')}"><div class="tb-eq-body">${q.html}</div><a class="tb-eq-num" href="${s.route}">(${q.num})</a></div>`).join('')}`).join('')}</section>`).join('');
  }

  /* ---------- exercises ---------- */
  function renderProblems() {
    document.title = 'Exercises · Little Neural Guide';
    const want = +((location.hash.split('?')[1] || '').match(/(?:^|&)ch=(\d+)/) || [])[1] || 0;
    const R = exGet(), all = B.chapters.flatMap(c => c.sections.flatMap(s => s.problems.map((_, k) => s.num + '.' + (k + 1)))), got = all.filter(id => R[id] === 'got').length, again = all.filter(id => R[id] === 'again').length;
    L().innerHTML = stHeader('Exercises and worked solutions', `${all.length} exercises from the core text: calculations, explanations and short derivations. Try each before opening its solution, then rate yourself; “Review again” items are collected at the top so you can return to them.`, `CORE TEXT · ${all.length} EXERCISES · ${got} SOLVED`)
      + `<div class="tb-ex-tools">${bar(got / all.length, `${got} solved · ${again} to review · ${all.length - got - again} not yet rated`)}
        <div class="tb-filter" role="group" aria-label="Show exercises of type"><button type="button" data-k="" aria-pressed="true">All</button>${Object.entries(KIND).map(([k, v]) => `<button type="button" data-k="${k}" aria-pressed="false">${v}</button>`).join('')}<button type="button" data-k="again" aria-pressed="false">To review</button><button type="button" data-k="new" aria-pressed="false">Not yet rated</button></div>
        <label class="tb-chsel">Chapter <select id="tb-exch"><option value="0">All chapters</option>${B.chapters.map(c => `<option value="${c.n}" ${c.n === want ? 'selected' : ''}>${c.n}. ${esc(chTitleText(c))}</option>`).join('')}</select></label></div>`
      + B.chapters.map(c => `<section class="lesson-section tb-exch" data-ch="${c.n}" ${want && want !== c.n ? 'hidden' : ''}><p class="eyebrow">Chapter ${c.n}</p><h2>${c.title}</h2>${c.sections.map(s => `<h3><a href="${s.route}">§${s.num} ${esc(label(s.route))}</a></h3>${problemsHTML(s)}`).join('')}</section>`).join('');
    const apply = () => {
      const k = (L().querySelector('.tb-filter [aria-pressed="true"]') || {}).dataset?.k || '', ch = +L().querySelector('#tb-exch').value, R2 = exGet();
      L().querySelectorAll('.tb-exch').forEach(sec => { sec.hidden = ch && +sec.dataset.ch !== ch; });
      L().querySelectorAll('.tb-problem').forEach(li => { const id = li.dataset.ex, kind = (li.querySelector('.tb-kind').className.match(/tb-k-(\w+)/) || [])[1]; li.hidden = !!k && !(k === kind || (k === 'again' && R2[id] === 'again') || (k === 'new' && !R2[id])); });
    };
    L().querySelector('.tb-filter').addEventListener('click', ev => { const b = ev.target.closest('button'); if (!b) return; L().querySelectorAll('.tb-filter button').forEach(x => x.setAttribute('aria-pressed', x === b)); apply(); });
    L().querySelector('#tb-exch').addEventListener('change', apply);
  }

  /* ---------- contents (prepended to the study hub) ---------- */
  function contentsHTML() {
    const vis = (() => { try { return ngVisited(); } catch (e) { return new Set(); } })(), R = exGet();
    return `<section class="tb-contents" id="tb-contents"><p class="eyebrow">The core text</p><h2>Contents</h2><p class="muted">Ten chapters in five parts. Each section is a lesson page with a full textbook treatment, numbered equations, worked examples and exercises with solutions. Read a chapter as one page, or work through the interactive sections.</p>
      <div class="tb-backmatter"><a class="secondary" href="/study/read/1/">Start reading: Chapter 1</a><a class="secondary" href="/study/glossary/">Glossary</a><a class="secondary" href="/study/equations/">Key equations</a><a class="secondary" href="/study/problems/">Exercises & solutions</a></div>
      ${Object.keys(B.parts).map(p => `<div class="tb-part"><p class="tb-partname">Part ${p} · ${esc(B.parts[p])}</p>${B.chapters.filter(c => c.part === p).map(c => {
        const seen = c.sections.filter(s => vis.has(s.route)).length, nEx = c.sections.reduce((a, s) => a + s.problems.length, 0), sol = c.sections.reduce((a, s) => a + s.problems.filter((_, k) => R[s.num + '.' + (k + 1)] === 'got').length, 0);
        return `<div class="tb-chrow"><div class="tb-chhead"><a href="${overviewOf(c)}"><span class="tb-chn">${c.n}</span>${c.title}</a><span class="tb-chmeta">${seen}/4 sections · ${sol}/${nEx} exercises · <a href="/study/read/${c.n}/">read as one page</a></span></div>
          <ol class="tb-chsecs">${c.sections.map(s => `<li class="${vis.has(s.route) ? 'seen' : ''}"><a href="${s.route}"><b>${s.num}</b> ${esc(label(s.route))}</a></li>`).join('')}</ol></div>`;
      }).join('')}</div>`).join('')}</section>`;
  }

  /* ---------- routing: wrap the study hub ---------- */
  const SUBS = { glossary: 1, equations: 1, problems: 1, read: 1 };
  const origRender = window.renderStudy;
  window.renderStudy = function (slug) {
    if (slug === 'read') { const n = +(PATH().split('/')[3] || 1); return renderReader(n); }
    if (slug === 'glossary') return renderGlossary();
    if (slug === 'equations') return renderEquations();
    if (slug === 'problems') return renderProblems();
    origRender.apply(this, arguments);
    if (!slug) { const Ls = L(), tabs = Ls.querySelector('.st-tabs'); if (tabs && !Ls.querySelector('.tb-contents')) tabs.insertAdjacentHTML('afterend', contentsHTML()); const comp = [...Ls.querySelectorAll('.st-part')][0]; if (comp && !Ls.querySelector('.tb-comp-h')) comp.insertAdjacentHTML('beforebegin', '<div class="tb-comp-h"><p class="eyebrow">Beyond the core text</p><h2>Companion pages by area</h2><p class="muted">Labs, workbenches, research and practice pages, grouped by area, with what you have opened.</p></div>'); }
  };
  const origNav = window.studyNavPages;
  window.studyNavPages = () => { const a = origNav ? origNav() : []; return [a[0], ['/study/read/1/', 'Read the core text (Chapters 1–10)'], ['/study/glossary/', 'Glossary'], ['/study/equations/', 'Key equations'], ['/study/problems/', 'Exercises & solutions'], ...a.slice(1)]; };

  /* ---------- flashcards: glossary and exercise decks ---------- */
  if (typeof cardBank === 'function') {
    const origBank = cardBank;
    // eslint-disable-next-line no-global-assign
    cardBank = function () {
      const cards = origBank();
      Object.entries(B.glossary).forEach(([id, g]) => cards.push({ id: 'tbg-' + id, deck: 'Textbook terms', front: `Define: <b>${g.term}</b>`, back: g.def, href: g.route || '/study/glossary/' }));
      B.chapters.forEach(c => c.sections.forEach(s => s.problems.forEach((p, k) => { if (p.kind !== 'derive') cards.push({ id: `tbx-${s.num}.${k + 1}`, deck: 'Textbook exercises', front: `<small>Exercise ${s.num}.${k + 1}</small><br>${p.q}`, back: p.a, href: s.route }); })));
      return cards;
    };
  }

  /* ---------- search: add the textbook text to the index (before ngsearch.js builds it) ---------- */
  try {
    if (typeof GUIDE_CORPUS !== 'undefined' && window.NG_BOOK_CORPUS && !GUIDE_CORPUS.__tb) {
      let i = 0; GUIDE_CORPUS.__tb = 1;
      NG_BOOK_CORPUS.forEach(x => GUIDE_CORPUS.chunks.push({ id: 'tb' + (i++), route: x.route, page: label(x.route), heading: x.heading, text: x.text }));
      Object.entries(B.glossary).forEach(([id, g]) => GUIDE_CORPUS.chunks.push({ id: 'tb' + (i++), route: '/study/glossary/', page: 'Glossary', heading: g.plain, text: strip(g.def) }));
    }
  } catch (e) {}

  /* ---------- term pop-ups ---------- */
  const pop = document.createElement('div'); pop.className = 'tb-pop'; pop.hidden = true; pop.setAttribute('role', 'tooltip'); pop.id = 'tb-pop'; document.body.appendChild(pop);
  let popFor = null, hideT = 0;
  function showPop(el) {
    const g = B.glossary[el.dataset.term]; if (!g) return; clearTimeout(hideT); popFor = el;
    pop.innerHTML = `<p class="tb-pop-term">${g.term}</p><p>${g.def}</p><p class="tb-pop-links">${g.sec ? `<a href="${g.route}">§${g.sec}</a> · ` : ''}<a href="/study/glossary/?t=${el.dataset.term}">Glossary</a></p>`;
    pop.hidden = false; el.setAttribute('aria-describedby', 'tb-pop');
    const r = el.getBoundingClientRect(), pw = Math.min(340, window.innerWidth - 24); pop.style.width = pw + 'px';
    let x = Math.min(Math.max(12, r.left + r.width / 2 - pw / 2), window.innerWidth - pw - 12), y = r.bottom + 8;
    pop.style.left = (x + window.scrollX) + 'px'; pop.style.top = (y + window.scrollY) + 'px';
    const ph = pop.offsetHeight; if (r.bottom + 8 + ph > window.innerHeight && r.top - ph - 8 > 0) pop.style.top = (r.top - ph - 8 + window.scrollY) + 'px';
  }
  const hidePop = (now) => { clearTimeout(hideT); hideT = setTimeout(() => { pop.hidden = true; if (popFor) popFor.removeAttribute('aria-describedby'); popFor = null; }, now ? 0 : 180); };
  document.addEventListener('mouseover', e => { const t = e.target.closest && e.target.closest('dfn.tb-term'); if (t) showPop(t); else if (e.target.closest && e.target.closest('.tb-pop')) clearTimeout(hideT); });
  document.addEventListener('mouseout', e => { if (e.target.closest && (e.target.closest('dfn.tb-term') || e.target.closest('.tb-pop'))) hidePop(); });
  document.addEventListener('focusin', e => { const t = e.target.closest && e.target.closest('dfn.tb-term'); if (t) showPop(t); });
  document.addEventListener('focusout', e => { if (e.target.closest && e.target.closest('dfn.tb-term')) hidePop(); });
  document.addEventListener('click', e => {
    const t = e.target.closest('dfn.tb-term'); if (t) { popFor === t && !pop.hidden ? hidePop(true) : showPop(t); return; }
    if (!e.target.closest('.tb-pop')) hidePop(true);
    const rb = e.target.closest('.tb-rate button');
    if (rb) { const li = rb.closest('.tb-problem'), id = li.dataset.ex, cur = exGet()[id], v = cur === rb.dataset.rate ? '' : rb.dataset.rate; exSet(id, v);
      L().querySelectorAll(`.tb-problem[data-ex="${id}"]`).forEach(x => { x.querySelectorAll('.tb-rate button').forEach(b => b.setAttribute('aria-pressed', b.dataset.rate === v)); const head = x.querySelector('.tb-phead'), old = head.querySelector('.tb-rated'); if (old) old.remove(); if (v) head.insertAdjacentHTML('beforeend', `<span class="tb-rated tb-r-${v}">${v === 'got' ? '✓ Solved' : '↻ Review again'}</span>`); }); }
    const cp = e.target.closest('.tb-copytex');
    if (cp) { const a = cp.closest('.tb-eq').querySelector('annotation'); const tex = a ? a.textContent : ''; const done = () => { cp.textContent = 'Copied'; setTimeout(() => cp.textContent = 'TeX', 1400); };
      try { navigator.clipboard.writeText(tex).then(done, () => fallback(tex, done)); } catch (err) { fallback(tex, done); } }
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && !pop.hidden) hidePop(true); if ((e.key === 'Enter' || e.key === ' ') && e.target.matches && e.target.matches('dfn.tb-term')) { e.preventDefault(); showPop(e.target); } });
  window.addEventListener('scroll', () => { if (!pop.hidden && popFor && !popFor.matches(':focus')) hidePop(true); }, { passive: true });
  function fallback(tex, done) { try { const ta = document.createElement('textarea'); ta.value = tex; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); done(); } catch (e) {} }

  window.addEventListener('beforeprint', () => document.querySelectorAll('.tb-sol').forEach(d => { d.open = true; }));

  /* ---------- apply after each render ---------- */
  function apply() {
    const Ls = L(); if (!Ls) return; const p = PATH();
    const e = SEC.get(p); if (e) decorateSection(Ls, e);
    const c = CH_BY_OVERVIEW.get(p); if (c) decorateChapter(Ls, c);
    Ls.querySelectorAll('.tb-eq').forEach(q => { if (!q.querySelector('.tb-copytex') && q.querySelector('annotation')) q.insertAdjacentHTML('beforeend', '<button type="button" class="tb-copytex" title="Copy the LaTeX source" aria-label="Copy LaTeX source of this equation">TeX</button>'); });
  }
  let q = 0; const later = () => { clearTimeout(q); q = setTimeout(apply, 30); };
  const prev = window.ngAfterRender; window.ngAfterRender = function (...a) { if (typeof prev === 'function') prev.apply(this, a); apply(); later(); };
  const L0 = L(); if (L0 && 'MutationObserver' in window) new MutationObserver(later).observe(L0, { childList: true });
  if (PATH().startsWith('/study/')) { try { window.renderGuide(); } catch (e) {} }
  later();
})();
